## Reed-Solomon 码

Reed-Solomon（RS）码是一类基于有限域运算的强大纠错码，广泛应用于 CD/DVD、QR 码和深空通信。RS 码在符号级别工作，能高效处理突发错误。一个 RS(n, k) 码可以纠正最多 t = (n-k)/2 个符号错误。

```typescript
class GaloisField {
  readonly size: number;
  private expTable: number[];
  private logTable: number[];

  constructor(
    private bits: number,
    private primitive: number,
  ) {
    this.size = (1 << bits) - 1;
    this.expTable = new Array(this.size * 2);
    this.logTable = new Array(this.size + 1);

    let x = 1;
    for (let i = 0; i < this.size; i++) {
      this.expTable[i] = x;
      this.logTable[x] = i;
      x <<= 1;
      if (x >= 1 << bits) {
        x ^= primitive;
        x &= (1 << bits) - 1;
      }
    }
    for (let i = this.size; i < this.size * 2; i++) {
      this.expTable[i] = this.expTable[i - this.size];
    }
  }

  multiply(a: number, b: number): number {
    if (a === 0 || b === 0) return 0;
    return this.expTable[(this.logTable[a] + this.logTable[b]) % this.size];
  }

  divide(a: number, b: number): number {
    if (b === 0) throw new Error('Division by zero');
    if (a === 0) return 0;
    return this.expTable[(this.logTable[a] - this.logTable[b] + this.size) % this.size];
  }

  add(a: number, b: number): number {
    return a ^ b;
  }

  power(a: number, n: number): number {
    if (a === 0) return 0;
    return this.expTable[(this.logTable[a] * n) % this.size];
  }

  exp(i: number): number {
    return this.expTable[i % this.size];
  }
}

function rsEncode(gf: GaloisField, message: number[], nsym: number): number[] {
  const gen: number[] = [1];
  for (let i = 0; i < nsym; i++) {
    const newGen = new Array(gen.length + 1).fill(0);
    const alpha = gf.exp(i);
    for (let j = 0; j < gen.length; j++) {
      newGen[j] = gf.add(newGen[j], gen[j]);
      newGen[j + 1] = gf.add(newGen[j + 1], gf.multiply(gen[j], alpha));
    }
    gen.length = 0;
    gen.push(...newGen);
  }

  const encoded = [...message, ...new Array(nsym).fill(0)];
  for (let i = 0; i < message.length; i++) {
    const coef = encoded[i];
    if (coef !== 0) {
      for (let j = 0; j < gen.length; j++) {
        encoded[i + j] = gf.add(encoded[i + j], gf.multiply(gen[j], coef));
      }
    }
  }
  return [...message, ...encoded.slice(message.length)];
}

const gf = new GaloisField(8, 0x11d);
const msg = [0x40, 0x73, 0x65];
const encoded = rsEncode(gf, msg, 4);
console.log(`RS 编码: [${encoded.map((x) => '0x' + x.toString(16)).join(', ')}]`);
```

| 应用领域   | RS 码参数    | 纠错能力 | 特点         |
| ---------- | ------------ | -------- | ------------ |
| QR 码 L 级 | RS(255, 247) | 4 符号   | 低冗余       |
| QR 码 H 级 | RS(255, 191) | 32 符号  | 高可靠性     |
| CD 音频    | RS(32, 28)   | 2 符号   | 交错编码     |
| 深空通信   | RS(255, 223) | 16 符号  | 与卷积码级联 |

## LDPC 码与现代编码

低密度校验码（LDPC）由 Gallager 于 1962 年发明，在 Tanner 图上通过置信传播（Belief Propagation）算法解码。LDPC 码能在复杂度为 O(n log n) 的条件下达到接近 Shannon 极限的性能。

```typescript
interface LDPCCode {
  n: number;
  k: number;
  checkMatrix: number[][];
}

function createRegularLDPC(n: number, wc: number, wr: number): LDPCCode {
  const m = Math.floor((n * wc) / wr);
  const k = n - m;
  const H: number[][] = Array.from({ length: m }, () => Array(n).fill(0));

  for (let j = 0; j < n; j++) {
    const positions: number[] = [];
    while (positions.length < wc) {
      const row = Math.floor(Math.random() * m);
      if (!positions.includes(row)) {
        positions.push(row);
      }
    }
    for (const row of positions) {
      H[row][j] = 1;
    }
  }

  return { n, k, checkMatrix: H };
}

function beliefPropagation(code: LDPCCode, received: number[], snr: number, maxIter: number = 50): number[] {
  const { n, checkMatrix: H } = code;
  const m = H.length;
  const sigma2 = 1 / (2 * snr);

  const llr = received.map((r) => (2 * r) / sigma2);

  const msgVC: number[][] = Array.from({ length: m }, () => Array(n).fill(0));
  const msgCV: number[][] = Array.from({ length: m }, () => Array(n).fill(0));

  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (H[i][j]) {
        msgVC[i][j] = llr[j];
      }
    }
  }

  for (let iter = 0; iter < maxIter; iter++) {
    for (let i = 0; i < m; i++) {
      const connectedVars: number[] = [];
      for (let j = 0; j < n; j++) {
        if (H[i][j]) connectedVars.push(j);
      }

      for (const j of connectedVars) {
        let product = 1;
        for (const jj of connectedVars) {
          if (jj !== j) {
            product *= Math.tanh(msgVC[i][jj] / 2);
          }
        }
        msgCV[i][j] = 2 * Math.atanh(Math.max(-0.9999, Math.min(0.9999, product)));
      }
    }

    for (let j = 0; j < n; j++) {
      for (let i = 0; i < m; i++) {
        if (H[i][j]) {
          let sum = llr[j];
          for (let ii = 0; ii < m; ii++) {
            if (ii !== i && H[ii][j]) {
              sum += msgCV[ii][j];
            }
          }
          msgVC[i][j] = sum;
        }
      }
    }
  }

  return llr.map((l, j) => {
    let total = l;
    for (let i = 0; i < m; i++) {
      if (H[i][j]) total += msgCV[i][j];
    }
    return total > 0 ? 0 : 1;
  });
}

const ldpc = createRegularLDPC(20, 3, 6);
console.log(`LDPC(${ldpc.n}, ${ldpc.k}) 创建完成`);
console.log(`校验矩阵维度: ${ldpc.checkMatrix.length} × ${ldpc.checkMatrix[0].length}`);
```

